```typescript
// Camera.ts
import { Vector3 } from 'three';

class Camera {
  private position: Vector3;
  private target: Vector3;
  private up: Vector3;
  private distance: number;
  private fov: number;

  constructor(position: Vector3, target: Vector3, up: Vector3, distance: number, fov: number) {
    this.position = position;
    this.target = target;
    this.up = up;
    this.distance = distance;
    this.fov = fov;
  }

  // Getters and setters
  get position() {
    return this.position;
  }

  set position(value: Vector3) {
    this.position = value;
  }

  get target() {
    return this.target;
  }

  set target(value: Vector3) {
    this.target = value;
  }

  get up() {
    return this.up;
  }

  set up(value: Vector3) {
    this.up = value;
  }

  get distance() {
    return this.distance;
  }

  set distance(value: number) {
    this.distance = value;
  }

  get fov() {
    return this.fov;
  }

  set fov(value: number) {
    this.fov = value;
  }

  // Methods
  public lookAt(target: Vector3) {
    this.target = target;
    this.update();
  }

  public update() {
    const direction = this.target.clone().sub(this.position);
    const right = new Vector3(1, 0, 0).cross(direction);
    const up = direction.clone().cross(right);

    this.up = up.normalize();
    this.right = right.normalize();
    this.position.add(direction.multiplyScalar(this.distance));
  }
}

// CameraAPI.ts
import { Camera } from './Camera';

class CameraAPI {
  private camera: Camera;

  constructor(camera: Camera) {
    this.camera = camera;
  }

  public lookAt(target: Vector3) {
    this.camera.lookAt(target);
  }

  public update() {
    this.camera.update();
  }
}

// App.ts
import { CameraAPI } from './CameraAPI';

const camera = new Camera(new Vector3(0, 0, 0), new Vector3(0, 0, 1), new Vector3(0, 1, 0), 10, 45);
const cameraAPI = new CameraAPI(camera);

cameraAPI.lookAt(new Vector3(0, 0, 1));
cameraAPI.update();
```

