```javascript
function updateInventory(item, quantity) {
  // Get the current inventory levels
  const currentQuantity = document.getElementById(`inventory-${item}`).textContent;

  // Update the inventory levels
  document.getElementById(`inventory-${item}`).textContent = currentQuantity + quantity;

  // Check if the inventory level is below the threshold
