import React, { useState } from 'react';
import './App.css';

function FoodList() {
  const [foods, setFoods] = useState([]);

  const handleAddFood = (e) => {
    e.preventDefault();
    const newFood = { name: e.target.name.value, type: e.target.type.value, spicinessLevel: e.target.spicinessLevel.value };
    setFoods([...foods, newFood]);
    e.target.reset();
  };

  const handleDeleteFood = (index) => {
    const newFoods = [...foods];
    newFoods.splice(index, 1);
    setFoods(newFoods);
  };

  return (
    <div className="App">
      <h1>Food List</h1>
      <form onSubmit={handleAddFood}>
        <label htmlFor="name">Name:</label>
        <input type="text" id="name" name="name" required />
        <label htmlFor="type">Type:</label>
        <input type="text" id="type" name="type" required />
        <label htmlFor="spicinessLevel">Spiciness Level:</label>
        <input type="number" id="spicinessLevel" name="spicinessLevel" required />
        <button type="submit">Add Food</button>
      </form>
      <ul>
        {foods.map((food, index) => (
          <li key={index}>
            {food.name} ({food.type}) - Spiciness Level: {food.spicinessLevel}
            <button onClick={() => handleDeleteFood(index)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default FoodList;
