Next, you can create a custom middleware class to extract the username from the JWT token. Here's an example:

```csharp
public class UsernameMiddleware
{
    private readonly RequestDelegate _next;
    private readonly IConfiguration _configuration;

    public UsernameMiddleware(RequestDelegate next, IConfiguration configuration)
    {
        _next = next;
        _configuration = configuration;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        // Get the JWT token from the authorization header
        var authHeader = context.Request.Headers["Authorization"];
        if (authHeader == null || !authHeader.StartsWith("Bearer "))
        {
            await _next(context);
            return;
        }

        // Extract the username from the JWT token
        var token = authHeader.Substring(7);
        var claims = JwtSecurityTokenHandler.ReadJwtToken(token, new TokenValidationParameters
        {
            ValidateIssuer = true,
            ValidateAudience = true,
            ValidateLifetime = true,
            ValidateIssuerSigningKey = true,
            ValidIssuer = _configuration["Jwt:Issuer"],
            ValidAudience = _configuration["Jwt:Audience"],
            IssuerSigningKey = _configuration["Jwt:Key"]
        });

        // Set the username in the context
        context.Items["Username"] = claims.Claims.FirstOrDefault(c => c.Type == ClaimTypes.NameIdentifier)?.Value;

        // Call the next middleware or controller
        await _next(context);
    }
}
```

Finally, you can add the `UsernameMiddleware` class to the `Configure` method in your `Startup.cs` file:

```csharp
public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
{
    app.UseMiddleware<UsernameMiddleware>();

    // ...
}
```

Now, you can access the username in your controllers or other middleware classes using the `context.Items["Username"]` property.

