    match = re.match(r'(-?\d+)\.(\d+)?e(\+?\d+)?', num_str)
    if not match:
        raise ValueError('Invalid scientific notation input')

    num = float(match.group(1))
    exp = int(match.group(3))

    words = english_number_to_words(num, lang)
    if exp > 0:
        words += ' times ten to the power of ' + str(exp)
    elif exp < 0:
