import { useCombobox } from "downshift";
import { fetchEmails } from "./fetchEmails";

const AutocompleteEmailInput = () => {
  const [emails, setEmails] = React.useState([]);
  const [inputValue, setInputValue] = React.useState("");

  const {
    isOpen,
    selectedItem,
    getMenuProps,
    getInputProps,
    getComboboxProps,
    highlightedIndex,
  } = useCombobox({
    items: emails,
    onSelect: (item) => {
      setInputValue(item);
      setEmails([]);
    },
    onInputValueChange: (inputValue) => {
      setInputValue(inputValue);
      fetchEmails(inputValue)
        .then((newEmails) => {
          setEmails(newEmails);
        })
        .catch((error) => {
          console.error(error);
        });
    },
  });

  const handleKeyDown = (event) => {
    if (event.key === "ArrowDown" && highlightedIndex !== null) {
      event.preventDefault();
      const nextIndex = highlightedIndex + 1;
      const newHighlightedIndex = (emails.length + nextIndex) % emails.length;
      setHighlightedIndex(newHighlightedIndex);
    }
  };

  return (
    <div {...getComboboxProps()}>
      <input
        {...getInputProps({
          placeholder: "Enter email address",
          value: inputValue,
          onChange: (event) => {
            setInputValue(event.target.value);
          },
          onKeyDown: handleKeyDown,
        })}
      />
      <ul {...getMenuProps()}>
        {isOpen &&
          emails.map((email, index) => (
            <li
              key={email}
              className={highlightedIndex === index ? "highlighted" : ""}
            >
              {email}
            </li>
          ))}
      </ul>
    </div>
  );
};

